#include <bits/stdc++.h>
using namespace std;

typedef long long ll;
const ll INF = 1e18;

struct Edge {
    int to;
    ll cost;
};

struct State {
    int node;
    ll fuel;
    ll dist;
    bool operator>(const State& other) const {
        return dist > other.dist;
    }
};

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int N, M, L;
    cin >> N >> M >> L;

    vector<int> station(N, 0);
    for (int i = 0; i < L; i++) {
        int s;
        cin >> s;
        s--;
        station[s] = 1;
    }

    int S, G;
    cin >> S >> G;
    S--; G--;

    vector<vector<Edge>> graph(N);
    for (int i = 0; i < M; i++) {
        int a, b;
        ll c;
        cin >> a >> b >> c;
        a--; b--;
        graph[a].push_back({b, c});
        graph[b].push_back({a, c});
    }

    ll tank;
    cin >> tank;

    // Dijkstra-like DP: dist[node][fuel] = min distance to reach node with fuel
    // But fuel can be up to tank (<= 10^5), N up to 300, so N*tank up to 3e7, might be large.
    // We'll use priority queue and only store states that are useful.

    vector<vector<ll>> dist(N, vector<ll>(tank + 1, INF));
    dist[S][tank] = 0;

    priority_queue<State, vector<State>, greater<State>> pq;
    pq.push({S, tank, 0});

    while (!pq.empty()) {
        auto [u, fuel, d] = pq.top();
        pq.pop();

        if (d != dist[u][fuel]) continue;

        // If at station, refill to full tank
        if (station[u] && fuel < tank) {
            if (d < dist[u][tank]) {
                dist[u][tank] = d;
                pq.push({u, tank, d});
            }
        }

        // Travel to neighbors
        for (auto& e : graph[u]) {
            if (e.cost > fuel) continue; // not enough fuel
            int nf = fuel - e.cost;
            if (d + e.cost < dist[e.to][nf]) {
                dist[e.to][nf] = d + e.cost;
                pq.push({e.to, nf, d + e.cost});
            }
        }
    }

    ll ans = INF;
    for (ll f = 0; f <= tank; f++) {
        ans = min(ans, dist[G][f]);
    }

    if (ans == INF) cout << -1 << "\n";
    else cout << ans << "\n";

    return 0;
}

