int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n, m, cap;
    while (cin >> n >> m >> cap) {
        if (n == 0 && m == 0 && cap == 0) break;

        int s, t;
        cin >> s >> t;
        --s; --t;

        int k;
        cin >> k;
        vector<int> station(n, 0);
        for (int i = 0; i < k; ++i) {
            int x;
            cin >> x;
            --x;
            station[x] = 1;
        }
        station[s] = 1;
        station[t] = 1;

        const long long INF = (1LL << 60);

        vector<vector<pair<int,int>>> g(n);
        for (int i = 0; i < m; ++i) {
            int a, b, d;
            cin >> a >> b >> d;
            --a; --b;
            g[a].push_back({b, d});
            g[b].push_back({a, d});
        }

        // State: (city, remaining fuel)
        vector<vector<long long>> dist(n, vector<long long>(cap + 1, INF));
        using State = tuple<long long,int,int>; // total distance, city, fuel
        priority_queue<State, vector<State>, greater<State>> pq;

        dist[s][cap] = 0;
        pq.push({0, s, cap});

        long long ans = -1;

        while (!pq.empty()) {
            auto [cd, u, fuel] = pq.top();
            pq.pop();
            if (cd != dist[u][fuel]) continue;

            if (u == t) {
                ans = cd;
                break;
            }

            // Refill if station exists
            if (station[u] && fuel < cap) {
                if (cd < dist[u][cap]) {
                    dist[u][cap] = cd;
                    pq.push({cd, u, cap});
                }
            }

            // Move along roads
            for (auto [v, w] : g[u]) {
                if (w <= fuel) {
                    int nf = fuel - w;
                    long long nd = cd + w;
                    if (nd < dist[v][nf]) {
                        dist[v][nf] = nd;
                        pq.push({nd, v, nf});
                    }
                }
            }
        }

        cout << ans << '\n';
    }

    return 0;
}

