typedef struct {
    int x, y;
} Point;

double dist(Point a, Point b) {
    double dx = a.x - b.x;
    double dy = a.y - b.y;
    return sqrt(dx*dx + dy*dy);
}

int main() {
    int sx, sy, dx, dy;
    scanf("%d %d %d %d", &sx, &sy, &dx, &dy);

    int cap;
    scanf("%d", &cap);

    int n;
    scanf("%d", &n);

    Point points[n+2];
    points[0].x = sx; points[0].y = sy;
    for (int i = 0; i < n; i++) {
        scanf("%d %d", &points[i+1].x, &points[i+1].y);
    }
    points[n+1].x = dx; points[n+1].y = dy;

    int N = n + 2;
    int start = 0, dest = n+1;

    // adjacency list (only edges <= capacity)
    // we'll store in a simple matrix since N <= 100 typically
    double adj[N][N];
    for (int i = 0; i < N; i++)
        for (int j = 0; j < N; j++)
            adj[i][j] = -1;

    for (int i = 0; i < N; i++) {
        for (int j = i+1; j < N; j++) {
            double d = dist(points[i], points[j]);
            if (d <= cap + 1e-9) {
                adj[i][j] = d;
                adj[j][i] = d;
            }
        }
    }

    // Dijkstra
    double distTo[N];
    int visited[N];
    for (int i = 0; i < N; i++) {
        distTo[i] = 1e18;
        visited[i] = 0;
    }
    distTo[start] = 0;

    for (int k = 0; k < N; k++) {
        int u = -1;
        double minDist = 1e18;
        for (int i = 0; i < N; i++) {
            if (!visited[i] && distTo[i] < minDist) {
                minDist = distTo[i];
                u = i;
            }
        }
        if (u == -1) break;
        visited[u] = 1;
        if (u == dest) break;

        for (int v = 0; v < N; v++) {
            if (adj[u][v] >= 0 && !visited[v]) {
                double nd = distTo[u] + adj[u][v];
                if (nd < distTo[v]) {
                    distTo[v] = nd;
                }
            }
        }
    }

    if (distTo[dest] >= 1e17) {
        printf("-1\n");
    } else {
        printf("%.10f\n", distTo[dest]);
    }

    return 0;
}

