#define INF_LL ((long long)4e18)

typedef struct Edge {
    int to;
    int w;
    int next;
} Edge;

typedef struct HeapNode {
    long long d;
    int v;
} HeapNode;

typedef struct MinHeap {
    HeapNode *a;
    int size;
    int cap;
} MinHeap;

static void heap_init(MinHeap *h, int cap) {
    h->a = (HeapNode*)malloc(sizeof(HeapNode) * (cap + 1));
    h->size = 0;
    h->cap = cap;
}

static void heap_push(MinHeap *h, long long d, int v) {
    if (h->size + 1 > h->cap) {
        h->cap *= 2;
        h->a = (HeapNode*)realloc(h->a, sizeof(HeapNode) * (h->cap + 1));
    }
    int i = ++h->size;
    while (i > 1 && h->a[i/2].d > d) {
        h->a[i] = h->a[i/2];
        i /= 2;
    }
    h->a[i].d = d;
    h->a[i].v = v;
}

static HeapNode heap_pop(MinHeap *h) {
    HeapNode ret = h->a[1];
    HeapNode last = h->a[h->size--];
    int i = 1, child;
    while ((child = i * 2) <= h->size) {
        if (child + 1 <= h->size && h->a[child + 1].d < h->a[child].d) child++;
        if (h->a[child].d >= last.d) break;
        h->a[i] = h->a[child];
        i = child;
    }
    h->a[i] = last;
    return ret;
}

static int heap_empty(MinHeap *h) {
    return h->size == 0;
}

static void add_edge(int *head, Edge *edges, int *ecnt, int u, int v, int w) {
    edges[*ecnt].to = v;
    edges[*ecnt].w = w;
    edges[*ecnt].next = head[u];
    head[u] = (*ecnt)++;
}

static void dijkstra(int n, int *head, Edge *edges, int src, long long *dist) {
    for (int i = 0; i < n; i++) dist[i] = INF_LL;
    MinHeap h;
    heap_init(&h, n + 4);
    dist[src] = 0;
    heap_push(&h, 0, src);

    while (!heap_empty(&h)) {
        HeapNode cur = heap_pop(&h);
        long long d = cur.d;
        int u = cur.v;
        if (d != dist[u]) continue;
        for (int e = head[u]; e != -1; e = edges[e].next) {
            int v = edges[e].to;
            long long nd = d + edges[e].w;
            if (nd < dist[v]) {
                dist[v] = nd;
                heap_push(&h, nd, v);
            }
        }
    }
    free(h.a);
}

int main(void) {
    int N, M, K;
    long long L;
    /*
      Assumed input format:
      N M K L
      s t
      K integers: cities having LPG stations
      M lines: u v d   (1-indexed, undirected)

      Output:
      shortest distance from s to t with each segment between refuels <= L,
      where refueling is possible at start, destination, and listed LPG stations.
      If impossible, output -1.
    */
    if (scanf("%d %d %d %lld", &N, &M, &K, &L) != 4) return 0;

    int S, T;
    scanf("%d %d", &S, &T);
    S--; T--;

    int *isSpecial = (int*)calloc(N, sizeof(int));
    isSpecial[S] = 1;
    isSpecial[T] = 1;

    int *stations = (int*)malloc(sizeof(int) * K);
    for (int i = 0; i < K; i++) {
        scanf("%d", &stations[i]);
        stations[i]--;
        isSpecial[stations[i]] = 1;
    }

    int *head = (int*)malloc(sizeof(int) * N);
    for (int i = 0; i < N; i++) head[i] = -1;
    Edge *edges = (Edge*)malloc(sizeof(Edge) * (2 * M));
    int ecnt = 0;

    for (int i = 0; i < M; i++) {
        int u, v, d;
        scanf("%d %d %d", &u, &v, &d);
        u--; v--;
        add_edge(head, edges, &ecnt, u, v, d);
        add_edge(head, edges, &ecnt, v, u, d);
    }

    int specialCount = 0;
    for (int i = 0; i < N; i++) if (isSpecial[i]) specialCount++;

    int *special = (int*)malloc(sizeof(int) * specialCount);
    int *id = (int*)malloc(sizeof(int) * N);
    for (int i = 0; i < N; i++) id[i] = -1;

    int idx = 0;
    for (int i = 0; i < N; i++) {
        if (isSpecial[i]) {
            id[i] = idx;
            special[idx++] = i;
        }
    }

    int *metaHead = (int*)malloc(sizeof(int) * specialCount);
    for (int i = 0; i < specialCount; i++) metaHead[i] = -1;
    Edge *metaEdges = NULL;
    int metaCap = 16;
    int metaCnt = 0;
    metaEdges = (Edge*)malloc(sizeof(Edge) * metaCap);

    long long *dist = (long long*)malloc(sizeof(long long) * N);

    for (int i = 0; i < specialCount; i++) {
        dijkstra(N, head, edges, special[i], dist);
        for (int j = i + 1; j < specialCount; j++) {
            if (dist[special[j]] <= L) {
                if (metaCnt + 2 > metaCap) {
                    metaCap *= 2;
                    metaEdges = (Edge*)realloc(metaEdges, sizeof(Edge) * metaCap);
                }
                add_edge(metaHead, metaEdges, &metaCnt, i, j, (int)dist[special[j]]);
                add_edge(metaHead, metaEdges, &metaCnt, j, i, (int)dist[special[j]]);
            }
        }
    }

    long long *metaDist = (long long*)malloc(sizeof(long long) * specialCount);
    dijkstra(specialCount, metaHead, metaEdges, id[S], metaDist);

    if (metaDist[id[T]] >= INF_LL / 2) printf("-1\n");
    else printf("%lld\n", metaDist[id[T]]);

    free(isSpecial);
    free(stations);
    free(head);
    free(edges);
    free(special);
    free(id);
    free(metaHead);
    free(metaEdges);
    free(dist);
    free(metaDist);

    return 0;
}

import java.util.*;

public class Main {
    static class Edge {
        int to;
        long dist;

        Edge(int to, long dist) {
            this.to = to;
            this.dist = dist;
        }
    }

    static class State implements Comparable<State> {
        int node;
        long dist;
        int fuel;

        State(int node, long dist, int fuel) {
            this.node = node;
            this.dist = dist;
            this.fuel = fuel;
        }

        @Override
        public int compareTo(State other) {
            if (this.dist != other.dist) {
                return Long.compare(this.dist, other.dist);
            }
            return Integer.compare(this.fuel, other.fuel);
        }
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);

        int N = sc.nextInt();
        int M = sc.nextInt();
        int L = sc.nextInt();
        int start = sc.nextInt() - 1;
        int dest = sc.nextInt() - 1;
        int capacity = sc.nextInt();

        // Build graph
        List<List<Edge>> graph = new ArrayList<>();
        for (int i = 0; i < N; i++) {
            graph.add(new ArrayList<>());
        }

        for (int i = 0; i < M; i++) {
            int u = sc.nextInt() - 1;
            int v = sc.nextInt() - 1;
            int d = sc.nextInt();
            graph.get(u).add(new Edge(v, d));
            graph.get(v).add(new Edge(u, d));
        }

        // LPG stations (0-indexed)
        Set<Integer> stations = new HashSet<>();
        for (int i = 0; i < L; i++) {
            stations.add(sc.nextInt() - 1);
        }
        stations.add(start); // Start city also has LPG
        stations.add(dest);   // Destination city also has LPG

        // Dijkstra's algorithm with fuel state
        // dist[node][fuel] = minimum distance to reach node with given fuel
        long[][] dist = new long[N][capacity + 1];
        for (int i = 0; i < N; i++) {
            Arrays.fill(dist[i], Long.MAX_VALUE);
        }

        // Priority queue
        PriorityQueue<State> pq = new PriorityQueue<>();

        // Start with full tank
        dist[start][capacity] = 0;
        pq.offer(new State(start, 0, capacity));

        while (!pq.isEmpty()) {
            State curr = pq.poll();

            if (curr.dist != dist[curr.node][curr.fuel]) {
                continue;
            }

            // If we reached destination, we're done
            if (curr.node == dest) {
                System.out.println(curr.dist);
                return;
            }

            // Try to go to adjacent cities
            for (Edge edge : graph.get(curr.node)) {
                if (curr.fuel >= edge.dist) {
                    int newFuel = curr.fuel - (int)edge.dist;

                    // If we can refill at the destination, do so
                    if (stations.contains(edge.to)) {
                        newFuel = capacity;
                    }

                    long newDist = curr.dist + edge.dist;

                    if (newDist < dist[edge.to][newFuel]) {
                        dist[edge.to][newFuel] = newDist;
                        pq.offer(new State(edge.to, newDist, newFuel));
                    }
                }
            }

            // If current node is a station, we can refill
            if (stations.contains(curr.node) && curr.fuel < capacity) {
                if (curr.dist < dist[curr.node][capacity]) {
                    dist[curr.node][capacity] = curr.dist;
                    pq.offer(new State(curr.node, curr.dist, capacity));
                }
            }
        }

        // If no path found
        System.out.println("-1");
    }
}

import java.io.*;
import java.util.*;

/*
 * Taxi route with fuel constraints.
 *
 * Model:
 * - Cities are vertices, roads are weighted undirected edges.
 * - Some cities have LPG stations; start and destination are also usable stops.
 * - Tank capacity = L. The taxi can travel at most L distance between two refuels.
 * - We need the minimum total travel distance from start to destination.
 *
 * Standard approach:
 * 1) Compute all-pairs shortest paths between cities (Floyd-Warshall).
 * 2) Build a reduced graph whose nodes are only "important" cities:
 *      start, destination, and all LPG station cities.
 *    Add an edge between two important cities if their shortest city-to-city
 *    distance is <= L; that edge weight is that shortest distance.
 * 3) Run Dijkstra on the reduced graph from start to destination.
 *
 * Assumed input format:
 *   n m
 *   u1 v1 d1
 *   ...
 *   um vm dm
 *   k
 *   s1 s2 ... sk        (LPG station city numbers)
 *   c
 *   start destination
 *
 * Cities are 1-indexed in input.
 *
 * If destination is unreachable, output -1.
 */
public class Main {
    static final long INF = Long.MAX_VALUE / 4;

    static class FastScanner {
        private final InputStream in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        FastScanner(InputStream is) {
            in = is;
        }

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        int nextInt() throws IOException {
            int c;
            do {
                c = read();
            } while (c <= ' ' && c != -1);
            int sign = 1;
            if (c == '-') {
                sign = -1;
                c = read();
            }
            int val = 0;
            while (c > ' ') {
                val = val * 10 + (c - '0');
                c = read();
            }
            return val * sign;
        }

        long nextLong() throws IOException {
            int c;
            do {
                c = read();
            } while (c <= ' ' && c != -1);
            int sign = 1;
            if (c == '-') {
                sign = -1;
                c = read();
            }
            long val = 0;
            while (c > ' ') {
                val = val * 10 + (c - '0');
                c = read();
            }
            return val * sign;
        }
    }

    static class Edge {
        int to;
        long w;
        Edge(int to, long w) {
            this.to = to;
            this.w = w;
        }
    }

    static class Node implements Comparable<Node> {
        int v;
        long d;
        Node(int v, long d) {
            this.v = v;
            this.d = d;
        }
        public int compareTo(Node o) {
            return Long.compare(this.d, o.d);
        }
    }

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner(System.in);

        int n;
        try {
            n = fs.nextInt();
        } catch (Exception e) {
            return;
        }
        int m = fs.nextInt();

        long[][] dist = new long[n][n];
        for (int i = 0; i < n; i++) {
            Arrays.fill(dist[i], INF);
            dist[i][i] = 0;
        }

        for (int i = 0; i < m; i++) {
            int u = fs.nextInt() - 1;
            int v = fs.nextInt() - 1;
            long d = fs.nextLong();
            if (d < dist[u][v]) {
                dist[u][v] = dist[v][u] = d;
            }
        }

        int k = fs.nextInt();
        boolean[] isStation = new boolean[n];
        for (int i = 0; i < k; i++) {
            int x = fs.nextInt() - 1;
            isStation[x] = true;
        }

        long L = fs.nextLong();
        int start = fs.nextInt() - 1;
        int goal = fs.nextInt() - 1;

        // Floyd-Warshall
        for (int mid = 0; mid < n; mid++) {
            for (int i = 0; i < n; i++) {
                if (dist[i][mid] == INF) continue;
                for (int j = 0; j < n; j++) {
                    if (dist[mid][j] == INF) continue;
                    long nd = dist[i][mid] + dist[mid][j];
                    if (nd < dist[i][j]) dist[i][j] = nd;
                }
            }
        }

        // Build important nodes: start, goal, and all stations
        ArrayList<Integer> important = new ArrayList<>();
        boolean[] used = new boolean[n];
        important.add(start);
        used[start] = true;
        if (!used[goal]) {
            important.add(goal);
            used[goal] = true;
        }
        for (int i = 0; i < n; i++) {
            if (isStation[i] && !used[i]) {
                important.add(i);
                used[i] = true;
            }
        }

        int p = important.size();
        List<Edge>[] g = new ArrayList[p];
        for (int i = 0; i < p; i++) g[i] = new ArrayList<>();

        for (int i = 0; i < p; i++) {
            int a = important.get(i);
            for (int j = i + 1; j < p; j++) {
                int b = important.get(j);
                if (dist[a][b] <= L) {
                    g[i].add(new Edge(j, dist[a][b]));
                    g[j].add(new Edge(i, dist[a][b]));
                }
            }
        }

        int sIdx = 0;
        int tIdx = (important.get(0) == goal ? 0 : 1);

        long[] best = new long[p];
        Arrays.fill(best, INF);
        best[sIdx] = 0;
        PriorityQueue<Node> pq = new PriorityQueue<>();
        pq.add(new Node(sIdx, 0));

        while (!pq.isEmpty()) {
            Node cur = pq.poll();
            if (cur.d != best[cur.v]) continue;
            if (cur.v == tIdx) break;
            for (Edge e : g[cur.v]) {
                long nd = cur.d + e.w;
                if (nd < best[e.to]) {
                    best[e.to] = nd;
                    pq.add(new Node(e.to, nd));
                }
            }
        }

        System.out.println(best[tIdx] >= INF / 2 ? -1 : best[tIdx]);
    }
}

import heapq

def dijkstra(graph, start, n):
    dist = [float('inf')] * (n + 1)
    dist[start] = 0
    pq = [(0, start)]
    while pq:
        d, u = heapq.heappop(pq)
        if d > dist[u]:
            continue
        for v, w in graph[u]:
            if dist[u] + w < dist[v]:
                dist[v] = dist[u] + w
                heapq.heappush(pq, (dist[v], v))
    return dist

